// Hand-written (NOT autogenerated). Guards the union and vector serialization
// that tools/ulsdkbuild emits: a Query built from the high-level types must
// carry its union payloads on the wire, as read by the low-level flatc
// bindings, and must not carry vectors that the caller did not set.

package query

import (
	"bytes"
	"reflect"
	"testing"

	flatbuffers "github.com/google/flatbuffers/go"
	"github.com/urbanlogiq/ulsdk/types/fun"
	"github.com/urbanlogiq/ulsdk/types/generated"
	"github.com/urbanlogiq/ulsdk/types/id"
	"github.com/urbanlogiq/ulsdk/types/value"
)

var streamID = []byte{
	0x05, 0x00, 0x79, 0x31, 0x4d, 0x58, 0x42, 0x4e,
	0xbe, 0x80, 0xe0, 0x80, 0xc2, 0x71, 0x5f, 0x7c,
}

// selectQuery is `SELECT name FROM t WHERE name = $0`, with t bound to a
// data catalog stream and $0 bound to the string "x".
func selectQuery() *Query {
	name := &Column{Name: "name"}
	return &Query{
		Query: QueryElement{Q: &UnaryQueryElement{
			Sources: []TableSource{{T: &Placeholder{Idx: 0}}},
			Fields:  []Expr{{Exprs: name}},
			Filter: &Function{
				Fn:         int16(fun.FnEqual),
				Parameters: []Expr{{Exprs: name}, {Exprs: &ValueIndex{Idx: 0}}},
			},
		}},
		Values:       []value.ValueInstance{{V: &value.Vstr{V: "x"}}},
		BoundSources: []TableSourceInstance{{T: &DataCatalog{Id: id.ObjectId{B: streamID}}}},
	}
}

func TestQueryUnionsOnWire(t *testing.T) {
	q := generated.GetSizePrefixedRootAsQuery(selectQuery().ToBytes(), 0)
	var tbl flatbuffers.Table

	if got := q.Query(nil).QType(); got != generated.QueryElementUnionUnaryQueryElement {
		t.Fatalf("query type = %v, want UnaryQueryElement", got)
	}

	var src generated.TableSourceInstance
	if !q.BoundSources(&src, 0) || src.TType() != generated.TableSourceUnionDataCatalog || !src.T(&tbl) {
		t.Fatalf("bound source is not a DataCatalog (type %v)", src.TType())
	}
	var dc generated.DataCatalog
	dc.Init(tbl.Bytes, tbl.Pos)
	if got := dc.Id(nil).BBytes(); !bytes.Equal(got, streamID) {
		t.Fatalf("data catalog id = %x, want %x", got, streamID)
	}

	var val generated.ValueInstance
	if !q.Values(&val, 0) || val.VType() != generated.ValueVStr || !val.V(&tbl) {
		t.Fatalf("value is not a VStr (type %v)", val.VType())
	}
	var s generated.VStr
	s.Init(tbl.Bytes, tbl.Pos)
	if got := string(s.V()); got != "x" {
		t.Fatalf("value = %q, want %q", got, "x")
	}
}

func TestQueryRoundTrip(t *testing.T) {
	want := selectQuery()
	got, err := QueryFromBytes(want.ToBytes())
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(got.Query, want.Query) {
		t.Fatalf("query element:\n got %#v\nwant %#v", got.Query.Q, want.Query.Q)
	}
	if !reflect.DeepEqual(got.Values, want.Values) {
		t.Fatalf("values:\n got %#v\nwant %#v", got.Values, want.Values)
	}
	if !reflect.DeepEqual(got.BoundSources, want.BoundSources) {
		t.Fatalf("bound sources:\n got %#v\nwant %#v", got.BoundSources, want.BoundSources)
	}
}

func TestUnionRejectsNonPointerVariant(t *testing.T) {
	defer func() {
		if recover() == nil {
			t.Fatal("expected a panic for a non-pointer variant")
		}
	}()
	(&TableSourceInstance{T: DataCatalog{}}).ToBytes()
}

// insertQuery is `INSERT INTO t (name) VALUES ($0)`, with t bound to a data
// catalog stream and $0 bound to the string "x". Returning is not set.
func insertQuery() *Query {
	return &Query{
		Query: QueryElement{Q: &InsertQueryElement{
			Source: QueryElement{Q: &UnaryQueryElement{
				Sources: []TableSource{{T: &Values{
					Rows: []ValueRow{{Row: []Expr{{Exprs: &ValueIndex{Idx: 0}}}}},
				}}},
			}},
			Columns: []string{"name"},
			Dest:    &Placeholder{Idx: 0},
		}},
		Values:       []value.ValueInstance{{V: &value.Vstr{V: "x"}}},
		BoundSources: []TableSourceInstance{{T: &DataCatalog{Id: id.ObjectId{B: streamID}}}},
	}
}

// vtable slots, as the flatc accessors in query_generated.go read them.
const (
	insertReturningSlot flatbuffers.VOffsetT = 14
	unaryFieldsSlot     flatbuffers.VOffsetT = 10
	sourceFieldsSlot    flatbuffers.VOffsetT = 8
)

// An empty `returning` makes the server return zero columns, which fails.
// An empty `fields` on the VALUES source is accepted, but must stay absent.
func TestInsertOmitsUnsetVectors(t *testing.T) {
	q := generated.GetSizePrefixedRootAsQuery(insertQuery().ToBytes(), 0)
	var tbl flatbuffers.Table

	qe := q.Query(nil)
	if qe.QType() != generated.QueryElementUnionInsertQueryElement || !qe.Q(&tbl) {
		t.Fatalf("query type = %v, want InsertQueryElement", qe.QType())
	}
	var ins generated.InsertQueryElement
	ins.Init(tbl.Bytes, tbl.Pos)
	if tab := ins.Table(); tab.Offset(insertReturningSlot) != 0 {
		t.Fatal("returning is written, want absent")
	}
	if ins.ColumnsLength() != 1 || string(ins.Columns(0)) != "name" {
		t.Fatalf("columns length = %d, want [name]", ins.ColumnsLength())
	}

	src := ins.Source(nil)
	if src.QType() != generated.QueryElementUnionUnaryQueryElement || !src.Q(&tbl) {
		t.Fatalf("source type = %v, want UnaryQueryElement", src.QType())
	}
	var unary generated.UnaryQueryElement
	unary.Init(tbl.Bytes, tbl.Pos)
	if tab := unary.Table(); tab.Offset(unaryFieldsSlot) != 0 {
		t.Fatal("source fields are written, want absent")
	}
	var ts generated.TableSource
	if !unary.Sources(&ts, 0) || ts.TType() != generated.TableSourceUnionValues {
		t.Fatalf("source table type = %v, want Values", ts.TType())
	}
	if tab := ts.Table(); tab.Offset(sourceFieldsSlot) != 0 {
		t.Fatal("VALUES fields are written, want absent")
	}
}
